pts=[(2,6),(2,12),(3,13),(4,13),(5,6),(5,7),(5,8),(5,10),(5,11),(5,12),(7,6),(8,13),(10,6),(10,12),(10,13)]
# pairs whose row/column changes by same absolute amount, diagonal or orthogonal, with one or more intermediate lattice cells
for i,p in enumerate(pts):
 for q in pts[i+1:]:
  dr=q[0]-p[0]; dc=q[1]-p[1]
  if dr==0 or dc==0 or abs(dr)==abs(dc):
   g=__import__('math').gcd(abs(dr),abs(dc))
   if g>1:
    step=(dr//g,dc//g)
    cells=[(p[0]+k*step[0],p[1]+k*step[1]) for k in range(1,g)]
    if cells: print(p,q,'gap',cells)
